/** Inactive root-admission hypothesis; no policy hook is installed by importing this file. */
import type { GameAction } from "./sources/common/src/engine/actions";
import type { IDecisionContext } from "./sources/common/src/ai/ai_strategy";
import type { Unit } from "./sources/common/src/units/unit";
import { PBTypes } from "./sources/common/src/generated/protobuf/v1/types";
import { getCellForPosition } from "./sources/common/src/grid/grid_math";
export function isActualMeleeBarrelRoot(unit:Unit,incumbent:readonly GameAction[],context:IDecisionContext|undefined):boolean {
 if(context?.decisionOrigin!=="root"||unit.getAttackTypeSelection()===PBTypes.AttackVals.RANGE)return false;
 const strike=incumbent.find(a=>a.type==="obstacle_attack");
 if(!strike||strike.type!=="obstacle_attack"||strike.attackerId!==unit.getId())return false;
 const cell=getCellForPosition(context.grid.getSettings(),strike.targetPosition);
 return context.grid.getArtifactBarrels().some(b=>b.cell.x===cell.x&&b.cell.y===cell.y);
}

import { test, expect } from "bun:test";
import { isActualMeleeBarrelRoot } from "./root-scope";
import { PBTypes } from "./sources/common/src/generated/protobuf/v1/types";
import { captureDeterministicRandomState } from "./sources/common/src/utils/lib";
const holder = (selection = PBTypes.AttackVals.MELEE) => ({ getId: () => "actor", getAttackTypeSelection: () => selection }) as any;
const context = (barrels: any[] = [{ cell: { x: 3, y: 5 }, team: 1 }], origin = "root") => ({ decisionOrigin: origin, grid: { getSettings: () => ({ getMaxX: () => 0, getCellSize: () => 10 }), getArtifactBarrels: () => barrels } }) as any;
const strike: any = { type: "obstacle_attack", attackerId: "actor", targetPosition: { x: 35, y: 55 } };
test("both armies' deployment barrels qualify at the exact real melee root", () => {
    for (const team of [1, 2]) expect(isActualMeleeBarrelRoot(holder(), [strike], context([{ cell: { x: 3, y: 5 }, team }]))).toBe(true);
});
test("ordinary shots, attacks, moves and holds stay outside the direct intervention", () => {
    for (const actions of [[{ type: "range_attack", attackerId: "actor", targetId: "enemy" }], [{ type: "melee_attack", attackerId: "actor", targetId: "enemy" }], [{ type: "move_unit", unitId: "actor", path: [] }], [{ type: "wait_turn", unitId: "actor" }], [{ type: "defend_turn", unitId: "actor" }], []]) expect(isActualMeleeBarrelRoot(holder(), actions as any, context())).toBe(false);
    expect(isActualMeleeBarrelRoot(holder(PBTypes.AttackVals.RANGE), [strike], context())).toBe(false);
});
test("neutral stones, other barrel cells, wrong actors and non-root calls stay native", () => {
    expect(isActualMeleeBarrelRoot(holder(), [strike], context([]))).toBe(false);
    expect(isActualMeleeBarrelRoot(holder(), [strike], context([{ cell: { x: 4, y: 5 }, team: 2 }]))).toBe(false);
    expect(isActualMeleeBarrelRoot(holder(), [{ ...strike, attackerId: "other" }], context())).toBe(false);
    for (const origin of ["rollout", "leaf", "reply", ""]) expect(isActualMeleeBarrelRoot(holder(), [strike], context(undefined, origin))).toBe(false);
    expect(isActualMeleeBarrelRoot(new Proxy({}, { get() { throw Error("No unit inspection without root context"); } }) as any, [strike], undefined)).toBe(false);
});
test("admission is deterministic, read-only and preserves random/UUID state and command references", () => {
    const before = captureDeterministicRandomState(), actions = Object.freeze([Object.freeze(strike)]), ctx = context(), unit = holder(), text = JSON.stringify(actions);
    for (let i = 0; i < 20; i++) expect(isActualMeleeBarrelRoot(unit, actions, ctx)).toBe(true);
    expect(actions[0]).toBe(strike); expect(JSON.stringify(actions)).toBe(text); expect(captureDeterministicRandomState()).toEqual(before);
});

import {isActualMeleeBarrelRoot} from "./root-scope";
import assert from "node:assert/strict";
import { appendFileSync } from "node:fs";
import { createInterface } from "node:readline";
import { gzipSync } from "node:zlib";
import { buildChoice } from "./build-choice";
import { fightNative, hash } from "./native";
import { SearchDriver } from "./sources/common/src/simulation/search_driver";
import { permuteRankedDraftSeed } from "./sources/common/src/simulation/ranked_draft_eval";
import { getA19NeuralModel } from "./sources/common/src/simulation/a19_neural_model";
import { loadLockedA19FullPolicyPair } from "./sources/common/src/simulation/v0_9/a19_full_policy_checkpoint";
import { V08_A19_PROFILE_SCHEMA } from "./sources/common/src/ai/versions/v0_8_a19_profile";
import { environment } from "./profiles";

assert.equal(V08_A19_PROFILE_SCHEMA, "hoc.v0_8_a19_production_profile.v11");
assert.equal(environment.SEARCH_A19_MELEE_BARREL_DELIBERATION, "1");
assert.equal(environment.SEARCH_A19_NIGHTMARE_WALL_MOVEMENT, "1");
assert.equal(environment.SEARCH_ROLLOUTS, "2");
assert.equal(environment.SEARCH_HORIZON, "64");
assert.equal(environment.SEARCH_A19_ROLLOUT_ALLOCATION, "uniform");
const [output, implementation] = process.argv.slice(2);
assert(["baseline", "candidate"].includes(implementation));
const g = globalThis as any, proto = SearchDriver.prototype as any;
const choose = proto.chooseDecision, model = getA19NeuralModel(), predict = model.predict;
const accepted = loadLockedA19FullPolicyPair();
assert.equal(accepted.pairSha256, "675b438406b6ee3aa313feb1e382843a0442bc9970bc28810abc19d30d26aa68");
model.predict = (observation: any) => {
    if (g.__mode === "accepted" && g.__modelActorTeam === g.__team) {
        g.__acceptedCalls++;
        return accepted.predict(observation);
    }
    return predict.call(model, observation);
};
proto.chooseDecision = function (unit: any, ...args: any[]) {
    g.__modelActorTeam = unit.getTeam();
    if (implementation === "candidate") {
        const eligible=isActualMeleeBarrelRoot(unit,args[1],args[2]);
        const scoped=(g.__mode === "scoped-both"||(g.__mode === "scoped"&&unit.getTeam()===g.__team))&&eligible;
        const active = scoped || g.__mode === "both" || (g.__mode === "mixture" && unit.getTeam() === g.__team);
        if(scoped){g.__scopedRoots++;if(g.__scopedWitnesses.length<8)g.__scopedWitnesses.push({unitId:unit.getId(),team:unit.getTeam(),lap:args[2].fightProperties.getCurrentLap(),incumbent:structuredClone(args[1])});}
        if(g.__mode === "scoped"||g.__mode === "scoped-both"){
          g.__scopedDecisions++;
          assert.equal(active,scoped,"No direct activation outside a registered actual melee-barrel root");
        }
        this.barrelForecastMixture = active;
        this.liveCertifiedBounds = active;
        if (active) g.__mixtureRoots++;
    }
    return choose.call(this, unit, ...args);
};

for await (const line of createInterface({ input: process.stdin })) {
    const { job, registrationSha256 } = JSON.parse(line);
    const team = (job.game < 2) === (job.game % 2 === 0) ? 2 : 1;
    const combatSeed = permuteRankedDraftSeed(job.seed + 6 + Number(job.game >= 2));
    const modes: string[] = job.modes ?? ["stock", "mixture", "accepted"];
    const rotation = (job.board + job.game) % modes.length;
    const ordered = [...modes.slice(rotation), ...modes.slice(0, rotation)];
    let consumedHash: string | undefined;
    for (const mode of ordered) {
        assert(implementation !== "baseline" || mode === "stock");
        g.__mode = "stock";
        g.__mixtureLiveMode = false;
        const built = buildChoice(job, "current", "current", team);
        if (job.draftConfigSha256) assert.equal(hash(built.drafted.config), job.draftConfigSha256[Number(job.game >= 2)]);
        const inputSha256 = hash({ config: built.opening.config, teams: built.opening.teams, terrain: built.opening.terrain, combatSeed });
        if (consumedHash) assert.equal(inputSha256, consumedHash, "An arm changed the funded native opening");
        consumedHash = inputSha256;
        if (job.expectedInputSha256) assert.equal(inputSha256, job.expectedInputSha256);
        g.__mode = mode;
        g.__team = team;
        g.__acceptedCalls = 0;
        g.__mixtureRoots = 0; g.__scopedRoots=0;g.__scopedDecisions=0;g.__scopedWitnesses=[];
        g.__mixtureLiveMode = !!job.live;
        const actualTurns: any[] = [], decisionMicros: any[] = [];
        g.__rushTurn = (r: any) => actualTurns.push({ unitId: r.unitId, creatureName: r.creatureName, rawIncumbent: r.rawIncumbent, chosenDecision: r.chosenDecision });
        g.__mixtureDecisionCompleted = (o: any) => {
            assert.equal(o.context.a19BarrelIntentForecast, undefined, "Projected flag reached an actual root");
            assert(Number.isFinite(o.context.decisionStartedAtMs));
            decisionMicros.push({ team: o.unit.getTeam(), micros: Math.max(0, Math.round((performance.now() - o.context.decisionStartedAtMs) * 1000)) });
        };
        const cpu = process.cpuUsage(), started = performance.now();
        const fought = fightNative(structuredClone(built.opening), combatSeed);
        const fightWallMicros = Math.round((performance.now() - started) * 1000), used = process.cpuUsage(cpu);
        assert.equal(fought.result.endReason, "elimination");
        const score = fought.result.winner === "draw" ? .5 : Number(fought.result.winner === (team === 2 ? "green" : "red"));
        if (mode === "mixture") assert(g.__mixtureRoots > 0);
        if (mode === "accepted") assert(g.__acceptedCalls > 0);
        for (const w of fought.quality.work) for (const k of ["deadlineFallbacks", "circuitSkipped", "circuitWaitArbitrations", "degradedDecisions"]) assert.equal(w[k] ?? 0, 0);
        if (job.expectedTraceSha256?.[mode]) {
            assert.equal(fought.traceSha256, job.expectedTraceSha256[mode]);
            assert.equal(score, job.expectedScore[mode]);
        }
        const row = { ...job, mode, implementation, team, registrationSha256, inputSha256, traceSha256: fought.traceSha256,
            score, winner: fought.result.winner, fightCpuMicros: used.user + used.system, fightWallMicros,
            decisionMicros, actualTurns, scopedRoots:g.__scopedRoots,scopedDecisions:g.__scopedDecisions,scopedWitnesses:g.__scopedWitnesses, mixtureRoots: g.__mixtureRoots, acceptedModelCalls: g.__acceptedCalls,
            acceptedPairSha256: mode === "accepted" ? accepted.pairSha256 : undefined, quality: fought.quality };
        const raw = JSON.stringify(row) + "\n";
        // Concatenated gzip members preserve every original JSONL byte; compression is outside all timers.
        appendFileSync(output, output.endsWith(".gz") ? gzipSync(raw, { level: 1 }) : raw);
    }
    console.log(JSON.stringify({ verified: true, board: job.board, game: job.game, rows: modes.length }));
}

from pathlib import Path
import concurrent.futures,datetime,gzip,hashlib,json,os,shutil,subprocess,threading,time

p=Path(__file__).resolve().parent
old=p.parent/'barrel-forecast-mixture-v11-confirmation-20261117'
regraw=(p/'registration.json').read_bytes();reg=json.loads(regraw);seal=hashlib.sha256(regraw).hexdigest()
sha=lambda b:hashlib.sha256(b).hexdigest()
state={'complete':False,'stage':'integrity','pid':os.getpid(),'registrationSha256':seal,'phaseCompleted':0,'errors':[],'newIndependentStrengthSamples':0,'defaultChanged':False}
lock=threading.Lock();processes=[];began=time.monotonic()
def read(name):return json.loads((p/name).read_text())
def write(name,obj):
 with(p/name).open('x')as f:json.dump(obj,f,indent=2,allow_nan=False);f.write('\n')
def save():
 with lock:
  state['at']=datetime.datetime.now(datetime.timezone.utc).isoformat();state['elapsedSeconds']=time.monotonic()-began
  tmp=p/'status.tmp';tmp.write_text(json.dumps(state,indent=2)+'\n');tmp.replace(p/'status.json')
def check():
 assert time.time()<reg['deadlineUnix'],'Fixed cutoff; no retry or extension'
 assert shutil.disk_usage(p).free>=reg['minimumFreeBytes']
def integrity():
 check()
 for f in reg['files']:assert sha((p/f['path']).read_bytes())==f['sha256'],f['path']
 assert sha((old/'strength-registration.json').read_bytes())==reg['parentRegistrationSha256']
 for f in json.loads((old/'strength-registration.json').read_text())['files']:
  assert sha((old/f['path']).read_bytes())==f['sha256'],f['path']
def rows(phase):
 for f in sorted((p/phase).glob('worker-*.jsonl.gz')):
  with gzip.open(f,'rt')as inp:
   for line in inp:yield json.loads(line)
def run_phase(name,jobs,workers):
 integrity();dest=p/name;dest.mkdir();state.update({'stage':name,'phaseCompleted':0,'phaseExpected':len(jobs),'workers':workers});save()
 def work(i):
  output=dest/f'worker-{i}.jsonl.gz'
  with(dest/f'worker-{i}.stderr.log').open('x')as log:
   proc=subprocess.Popen(['nice','-n','19','bun','--preload','./alias.ts','./actor.ts',str(output),'candidate'],cwd=p,stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=log,text=True,start_new_session=True)
   with lock:processes.append(proc)
   try:
    for job in jobs[i::workers]:
     check();proc.stdin.write(json.dumps({'job':job,'registrationSha256':seal},separators=(',',':'))+'\n');proc.stdin.flush()
     line=proc.stdout.readline();assert line,('Actor exited',i,proc.poll())
     ack=json.loads(line);assert ack['verified']and ack['board']==job['board']and ack['game']==job['game']and ack['rows']==len(job['modes'])
     with lock:state['phaseCompleted']+=1
     save()
    proc.stdin.close();assert proc.wait(timeout=30)==0
   finally:
    if proc.poll()is None:proc.terminate();proc.wait(timeout=10)
 with concurrent.futures.ThreadPoolExecutor(max_workers=workers)as pool:
  try:
   pending={pool.submit(work,i)for i in range(workers)}
   while pending:
    check();done,pending=concurrent.futures.wait(pending,timeout=5,return_when=concurrent.futures.FIRST_COMPLETED)
    for future in done:future.result()
  except BaseException:
   for proc in processes:
    if proc.poll()is None:proc.terminate()
   raise
 assert state['phaseCompleted']==len(jobs);integrity()
def quality(r):
 assert r['registrationSha256']==seal and r['score']in[0,.5,1]
 assert r['quality']['rejected']==0
 for n in r['quality']['neural']:
  for k in['modelErrors','missingStart','deadlineAbstentions','inferenceOverruns']:assert n[k]==0
 for w in r['quality']['work']:
  for k in['deadlineFallbacks','circuitSkipped','circuitWaitArbitrations','degradedDecisions']:assert w.get(k,0)==0
def stable(r):
 return{k:r[k]for k in['inputSha256','traceSha256','score','winner','actualTurns','quality','scopedRoots','scopedDecisions','scopedWitnesses']}
save()
try:
 integrity();cases=read('cases.json');index={(r['board'],r['game']):r['arms']for r in read('original-trace-index.json')}
 assert len(cases)==len(index)==6048 and len({c['board']for c in cases})==1512
 pre=read('preflight-cases.json');controls=read('preflight-controls.json')
 run_phase('preflight',[{**c,'modes':['stock','mixture','scoped','scoped-both']}for c in pre],2)
 checked=0;activated=0;seen=set()
 for r in rows('preflight'):
  quality(r);key=(r['board'],r['game'],r['mode']);assert key not in seen;seen.add(key)
  if r['mode']in['stock','mixture']:
   expected=controls[f"{r['board']}-{r['game']}-{r['mode']}"]
   for k in expected:assert r[k]==expected[k],(key,k)
   checked+=1
  else:activated+=r['scopedRoots']
 assert len(seen)==48 and checked==24 and activated>0
 write('preflight-verification.json',{'passed':True,'originalControls':checked,'executions':len(seen),'scopedActivations':activated,'newIndependentStrengthSamples':0})
 run_phase('collection',[{**c,'modes':['scoped']}for c in cases],reg['localWorkers'])
 cold=read('cold-cases.json')
 for epoch in[1,2]:run_phase(f'cold-{epoch}',[{**c,'modes':['scoped']}for c in cold],2)
 state['stage']='complete-bank-admission-analysis';save();integrity()
 cold_keys={(c['board'],c['game'])for c in cold};cold_main={};seen=set();counts={'stockHalfPoints':0,'mixtureHalfPoints':0,'scopedHalfPoints':0,'oldGains':0,'oldLosses':0,'scopedGains':0,'scopedLosses':0,'recoveredOldLossesFull':0,'recoveredOldLossesPartial':0,'oldGainsLostFull':0,'oldGainsLostPartial':0,'newLossesFromPreviouslyUnchanged':0,'untouchedExactCases':0,'scopedRoots':0,'scopedDecisions':0};cells={}
 for r in rows('collection'):
  quality(r);key=(r['board'],r['game']);assert key in index and key not in seen;seen.add(key);original=index[key];assert r['mode']=='scoped'and r['inputSha256']==original['stock']['inputSha256']==original['mixture']['inputSha256']
  a=int(2*original['stock']['score']);b=int(2*original['mixture']['score']);c=int(2*r['score'])
  counts['stockHalfPoints']+=a;counts['mixtureHalfPoints']+=b;counts['scopedHalfPoints']+=c
  counts['oldGains']+=b>a;counts['oldLosses']+=b<a;counts['scopedGains']+=c>a;counts['scopedLosses']+=c<a
  counts['recoveredOldLossesFull']+=b<a and c>=a;counts['recoveredOldLossesPartial']+=b<c<a
  counts['oldGainsLostFull']+=b>a and c<=a;counts['oldGainsLostPartial']+=a<c<b;counts['newLossesFromPreviouslyUnchanged']+=b==a and c<a
  counts['scopedRoots']+=r['scopedRoots'];counts['scopedDecisions']+=r['scopedDecisions']
  if not r['scopedRoots']:
   assert r['traceSha256']==original['stock']['traceSha256']and c==a;counts['untouchedExactCases']+=1
  for label,value in[('map',r['map']),('style',r['opponentStyle']),('ownDoctrine',r['ownDoctrine']),('opponentDoctrine',r['opponentDoctrine'])]:
   cell=cells.setdefault(f'{label}:{value}',{'cases':0,'stockHalfPoints':0,'mixtureHalfPoints':0,'scopedHalfPoints':0});cell['cases']+=1;cell['stockHalfPoints']+=a;cell['mixtureHalfPoints']+=b;cell['scopedHalfPoints']+=c
  if key in cold_keys:cold_main[key]=stable(r)
 assert len(seen)==6048 and len({a for a,b in seen})==1512 and len(cold_main)==36
 for epoch in[1,2]:
  got=set()
  for r in rows(f'cold-{epoch}'):
   quality(r);key=(r['board'],r['game']);assert key in cold_main and key not in got and stable(r)==cold_main[key];got.add(key)
  assert got==cold_keys
 gates={'allSourceInputQualityColdAndOriginalControlsExact':True,'scoreStrictlyHigherThanStock':counts['scopedHalfPoints']>counts['stockHalfPoints'],'scoreStrictlyHigherThanBroadMixture':counts['scopedHalfPoints']>counts['mixtureHalfPoints'],'fewerRegressionsThanBroadMixture':counts['scopedLosses']<counts['oldLosses'],'atLeast24ScopedRoots':counts['scopedRoots']>=24}
 result={'registrationSha256':seal,'complete':True,'cases':6048,'wholeFamilies':1512,'counts':counts,'slicesDescriptiveOnly':cells,'gates':gates,'passedReusedAdmission':all(gates.values()),'independentStrengthSamples':0,'defaultChanged':False,'testTeacherLabelsParsed':False,'elapsedSeconds':time.monotonic()-began,'interpretation':'Complete reused-bank diagnostic only; no new population strength or speed claim. Both gains and regressions retained. A pass only permits separately frozen current-v12 authoritative-memory qualification and overall-average+10% cost.'}
 write('analysis.json',result)
 with(p/'independent-verification.log').open('x')as log:subprocess.run(['nice','-n','19','bun','./verify.ts'],cwd=p,stdout=log,stderr=subprocess.STDOUT,check=True)
 assert read('independent-verification.json')['passed'];state.update({'complete':True,'stage':'complete-verified-reused-admission'})
except BaseException as error:
 state['errors'].append(repr(error));state['stage']='failed-preserve-all-no-retry'
 for proc in processes:
  if proc.poll()is None:proc.terminate()
 raise
finally:save()

